param([Parameter(Mandatory)][string]$Evidence, [int]$Samples = 7, [switch]$CandidateFirst, [switch]$CanonicalPaths,
    [string]$CandidateBuild = 'build\framework-pr', [switch]$IncludeSelection,
    [string]$BaselineBuild, [switch]$IncludeLong)
$ErrorActionPreference = 'Stop'
$root = 'D:\dev\copilot-worktrees\xui\zadjii-msft-probable-disco'
$baselineRoot = 'D:\dev\copilot-worktrees\xui\zadjii-msft-fantastic-tribble'
$baselineOutput = if ($BaselineBuild) { Join-Path $root $BaselineBuild } else { Join-Path $baselineRoot 'build\architecture-pristine' }
$baseline = Join-Path $baselineOutput 'Release'
$candidate = Join-Path "$root\$CandidateBuild" 'Release'
$probeBuild = if ($BaselineBuild) { 'build\ownership-baseline-full' } else { 'build\ownership-baseline' }
$probe = Join-Path $root "$probeBuild\xui_owned_children_probe.exe"
if (git -C $root status --porcelain) { throw 'Accepted timing requires a clean candidate' }
New-Item -ItemType Directory -Path $Evidence | Out-Null
$workloads = @(
    @{ name = 'owned'; baseline = $probe; candidate = "$candidate\xui_owned_children_probe.exe"; arguments = @() },
    @{ name = 'layout'; baseline = "$baseline\xui_layout_performance_tests.exe"; candidate = "$candidate\xui_layout_performance_tests.exe"; arguments = @('--benchmark') },
    @{ name = 'performance'; baseline = "$baseline\xui_performance_tests.exe"; candidate = "$candidate\xui_performance_tests.exe"; arguments = @('--benchmark') },
    @{ name = 'collections'; baseline = "$baseline\xui_collections_tests.exe"; candidate = "$candidate\xui_collections_tests.exe"; arguments = @('--benchmark') },
    @{ name = 'image'; baseline = "$baseline\xui_image_tests.exe"; candidate = "$candidate\xui_image_tests.exe"; arguments = @('--benchmark') }
)
if ($IncludeSelection) {
    $workloads += @{ name = 'selection_warm'; baseline = "$root\build\selection-probe\baseline.exe"; candidate = "$root\build\selection-probe\candidate.exe"; arguments = @() }
}
if ($IncludeLong) {
    $workloads += @{ name = 'long_warm'; baseline = "$root\build\long-probe\baseline.exe"; candidate = "$root\build\long-probe\candidate.exe"; arguments = @() }
}
if ($CanonicalPaths) {
    $frozen = Join-Path $root ("build\paired-binaries\" + (Split-Path $Evidence -Leaf))
    New-Item -ItemType Directory -Path "$frozen\baseline", "$frozen\proposed" -Force | Out-Null
    foreach ($workload in $workloads) {
        foreach ($revision in @('baseline', 'candidate')) {
            $directory = if ($revision -eq 'baseline') { 'baseline' } else { 'proposed' }
            $filename = if ($workload.name -eq 'selection_warm') { 'xui_selection_enumeration_probe.exe' } elseif ($workload.name -eq 'long_warm') { 'xui_layout_interaction_probe.exe' } else { Split-Path $workload[$revision] -Leaf }
            $target = Join-Path "$frozen\$directory" $filename
            if (Test-Path $target) { throw "Frozen artifact already exists: $target" }
            Copy-Item -LiteralPath $workload[$revision] -Destination $target
            $workload[$revision] = $target
        }
    }
}
$metadata = [ordered]@{
    candidate_commit = (git -C $root rev-parse HEAD)
    baseline_commit = '99016573d633636c54da71af5db247e5c249051e'
    baseline_output = $baselineOutput
    stock_optimizer_comparison = if ($BaselineBuild) { 'Matched full-/LTCG pristine versus full-/LTCG candidate; original source unchanged, separate outputs, CMAKE_PROJECT_INCLUDE adds the same directory link option.' } else { 'Preserved pristine real-default /LTCG:incremental versus candidate full-/LTCG.' }
    baseline_probe = 'Candidate test source with XUI_BASELINE_OWNED_CHILDREN, original readonly headers and baseline-specific core library; same MSVC x64 Release /O2 /Ob2 /GL /MT /LTCG'
    start = (Get-Date).ToString('o')
    warmups_per_version = 2
    recorded_per_version = $Samples
    candidate_starts_first = [bool]$CandidateFirst
    equal_length_frozen_executable_paths = [bool]$CanonicalPaths
    os = Get-CimInstance Win32_OperatingSystem | Select-Object Caption, Version, BuildNumber, TotalVisibleMemorySize
    cpu = Get-CimInstance Win32_Processor | Select-Object Name, NumberOfCores, NumberOfLogicalProcessors
    gpu = Get-CimInstance Win32_VideoController | Select-Object Name, DriverVersion
    power = (powercfg /GETACTIVESCHEME)
    session_name = $env:SESSIONNAME
    candidate_options = Get-Content "$root\$CandidateBuild\CMakeCache.txt" | Select-String '^(CMAKE_GENERATOR[^:]*|CMAKE_CXX_COMPILER[^:]*|XUI_ENABLE_IPO|XUI_REQUIRE_LSH|XUI_DESKTOP_TESTS):' | ForEach-Object Line
    baseline_options = Get-Content "$baselineOutput\CMakeCache.txt" | Select-String '^(CMAKE_GENERATOR[^:]*|CMAKE_CXX_COMPILER[^:]*|XUI_ENABLE_IPO|XUI_REQUIRE_LSH|XUI_DESKTOP_TESTS|CMAKE_PROJECT_INCLUDE):' | ForEach-Object Line
    baseline_layout_link = Get-ChildItem "$baselineOutput\xui_layout_performance_tests.dir\Release" -Recurse -Filter link.command.1.tlog | ForEach-Object { Get-Content $_.FullName -Raw }
    candidate_layout_link = Get-ChildItem "$root\$CandidateBuild\xui_layout_performance_tests.dir\Release" -Recurse -Filter link.command.1.tlog | ForEach-Object { Get-Content $_.FullName -Raw }
    baseline_core_compile = Get-ChildItem "$baselineOutput\xui_core.dir\Release" -Recurse -Filter CL.command.1.tlog | ForEach-Object { Get-Content $_.FullName -Raw }
    candidate_core_compile = Get-ChildItem "$root\$CandidateBuild\xui_core.dir\Release" -Recurse -Filter CL.command.1.tlog | ForEach-Object { Get-Content $_.FullName -Raw }
    pristine_matched_option = if ($BaselineBuild) { Get-Content "$PSScriptRoot\full-ltcg.cmake" -Raw } else { $null }
    baseline_probe_command = Get-Content "$root\$probeBuild\command.txt" -Raw
    baseline_probe_compiler = Get-Content "$root\$probeBuild\compile.log" -Raw
    baseline_library_hash = Get-FileHash "$baseline\xui_core.lib" -Algorithm SHA256
    candidate_library_hash = Get-FileHash "$candidate\xui_core.lib" -Algorithm SHA256
    probe_source_hashes = Get-FileHash "$root\tests\owned_children_probe.cpp", "$root\tests\owned_children_workload.hpp" -Algorithm SHA256
    selection_probe = if ($IncludeSelection) {
        @{
            source = Get-Content (Join-Path $PSScriptRoot 'selection_enumeration_probe.cpp') -Raw
            source_hash = Get-FileHash (Join-Path $PSScriptRoot 'selection_enumeration_probe.cpp')
            commands = Get-Content "$root\build\selection-probe\commands.txt" -Raw
            compiler = Get-Content "$root\build\selection-probe\compile.log" -Raw
            distinction = 'Warmed 10m/2m public selected_keys operations with exact identity, allocation/bytes/checksum and loop CPU checks. Not a replacement for the separate cold100-call stock results.'
        }
    } else { $null }
    long_probe = if ($IncludeLong) {
        @{
            source = Get-Content "$PSScriptRoot\layout_interaction_probe.cpp" -Raw
            source_hash = Get-FileHash "$PSScriptRoot\layout_interaction_probe.cpp"
            commands = Get-Content "$root\build\long-probe\commands.txt" -Raw
            compiler = Get-Content "$root\build\long-probe\compile.log" -Raw
            distinction = 'Identical 300k-frame nested Stack and 2m-operation million-row public interaction loops, warmed before checked loop CPU/wall snapshots; setup excluded. Exact geometry, measurement/identity/checksum/callback counts, zero allocations, shared view and bounded viewport checks.'
        }
    } else { $null }
    processes = Get-Process | Select-Object Id, ProcessName, CPU
    hashes = @($workloads | ForEach-Object { Get-FileHash $_.baseline, $_.candidate -Algorithm SHA256 })
}
$metadata | ConvertTo-Json -Depth 8 | Set-Content "$Evidence\environment.json"
$runs = [System.Collections.Generic.List[object]]::new()
foreach ($workload in $workloads) {
    foreach ($revision in @('baseline', 'candidate')) {
        foreach ($sample in 1..2) {
            $output = "$Evidence\$($workload.name)-warmup-$sample-$revision"
            $started = Get-Date
            $arguments = @{ FilePath = $workload[$revision]; PassThru = $true; NoNewWindow = $true; RedirectStandardOutput = "$output.out"; RedirectStandardError = "$output.err" }
            if ($workload.arguments.Count) { $arguments.ArgumentList = $workload.arguments }
            $process = Start-Process @arguments
            if (!$process.WaitForExit(120000)) { Stop-Process -Id $process.Id -Force; throw "Warmup timeout: $output" }
            $process.WaitForExit()
            $runs.Add(@{ workload = $workload.name; revision = $revision; phase = 'warmup'; sample = $sample; start = $started.ToString('o'); finish = (Get-Date).ToString('o'); exit = $process.ExitCode })
            $runs | ConvertTo-Json -Depth 5 | Set-Content "$Evidence\runs.json"
            if ($process.ExitCode) { throw "Warmup failure: $output" }
        }
    }
    foreach ($sample in 1..$Samples) {
        $order = if (($sample % 2 -eq 1) -xor [bool]$CandidateFirst) { @('baseline', 'candidate') } else { @('candidate', 'baseline') }
        foreach ($revision in $order) {
            $output = "$Evidence\$($workload.name)-$sample-$revision"
            $started = Get-Date
            $arguments = @{ FilePath = $workload[$revision]; PassThru = $true; NoNewWindow = $true; RedirectStandardOutput = "$output.out"; RedirectStandardError = "$output.err" }
            if ($workload.arguments.Count) { $arguments.ArgumentList = $workload.arguments }
            $process = Start-Process @arguments
            if (!$process.WaitForExit(120000)) { Stop-Process -Id $process.Id -Force; throw "Recorded timeout: $output" }
            $process.WaitForExit()
            $runs.Add(@{ workload = $workload.name; revision = $revision; phase = 'recorded'; sample = $sample; start = $started.ToString('o'); finish = (Get-Date).ToString('o'); exit = $process.ExitCode })
            $runs | ConvertTo-Json -Depth 5 | Set-Content "$Evidence\runs.json"
            if ($process.ExitCode) { throw "Recorded failure: $output" }
        }
    }
}
$metadata.finish = (Get-Date).ToString('o')
$metadata | ConvertTo-Json -Depth 8 | Set-Content "$Evidence\environment.json"

