#include "collections_fixture.hpp"
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <new>
#include <windows.h>
#include <psapi.h>

namespace {
thread_local bool counting{};
thread_local std::size_t calls{}, bytes{};
struct Cpu { std::uint64_t kernel, user; };
Cpu cpu() {
    FILETIME created{}, exited{}, kernel{}, user{};
    if (!GetThreadTimes(GetCurrentThread(), &created, &exited, &kernel, &user))
        throw std::runtime_error("Read selection traversal thread CPU");
    const auto ticks = [](FILETIME value) { return (std::uint64_t{value.dwHighDateTime} << 32) | value.dwLowDateTime; };
    return {ticks(kernel), ticks(user)};
}
SIZE_T memory() {
    PROCESS_MEMORY_COUNTERS_EX value{};
    if (!GetProcessMemoryInfo(GetCurrentProcess(), reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&value), sizeof(value)))
        throw std::runtime_error("Read selection traversal private memory");
    return value.PrivateUsage;
}
}
void* operator new(std::size_t size) {
    if (auto* value = std::malloc(size ? size : 1)) {
        if (counting) { ++calls; bytes += size; }
        return value;
    }
    throw std::bad_alloc{};
}
void* operator new[](std::size_t size) { return ::operator new(size); }
void operator delete(void* value) noexcept { std::free(value); }
void operator delete[](void* value) noexcept { std::free(value); }
void operator delete(void* value, std::size_t) noexcept { std::free(value); }
void operator delete[](void* value, std::size_t) noexcept { std::free(value); }
int main() {
    using namespace xui;
    using namespace collections_test;
    try {
        for (const std::size_t count : {1, 32}) {
            const auto source = std::make_shared<Rows>(count, true);
            CollectionSelection selection;
            selection.select_all(source, SelectAllScope::filtered);
            const auto enumerate = [&] {
                const auto keys = selection.selected_keys(source, count);
                require(keys && keys->size() == count && keys->front() == ItemKey{1, 1} &&
                    keys->back() == ItemKey{count, 1} && std::is_sorted(keys->begin(), keys->end()),
                    "Warmed enumeration returns the exact sorted identities");
                return keys->front().id + keys->back().id + keys->size();
            };
            for (int warmup = 0; warmup < 10000; ++warmup) enumerate();
            const std::size_t repeats = count == 1 ? 10000000 : 2000000;
            const auto before_memory = memory();
            calls = bytes = 0;
            const auto before_cpu = cpu();
            std::uint64_t sum{};
            counting = true;
            const auto start = std::chrono::steady_clock::now();
            for (std::size_t i = 0; i < repeats; ++i) sum += enumerate();
            const auto elapsed = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
            counting = false;
            const auto after_cpu = cpu();
            require(calls == repeats && bytes == repeats * count * sizeof(ItemKey) && sum == repeats * (2 * count + 1),
                "Warmed enumeration has exact allocation, byte and work counts");
            require(after_cpu.kernel >= before_cpu.kernel && after_cpu.user >= before_cpu.user, "Monotonic selection CPU");
            std::cout << "selection_warm rows=" << count << " warmups=10000 repeats=" << repeats
                << " allocations=" << calls << " allocated_bytes=" << bytes << " checksum=" << sum
                << " elapsed_ms=" << elapsed
                << " kernel_before_100ns=" << before_cpu.kernel << " kernel_after_100ns=" << after_cpu.kernel
                << " user_before_100ns=" << before_cpu.user << " user_after_100ns=" << after_cpu.user
                << " thread_cpu_ms=" << (after_cpu.kernel - before_cpu.kernel + after_cpu.user - before_cpu.user) / 10000.0
                << " private_before=" << before_memory << " private_after=" << memory() << '\n';
        }
        return 0;
    } catch (const std::exception& error) { std::cerr << error.what() << '\n'; return 1; }
}

