long_probe.source:
#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#define main unused_selection_probe_main
#include "selection_enumeration_probe.cpp"
#undef main
#include "xui/core.hpp"
#include "xui/control_styling.hpp"
#include "xui/file_list.hpp"
#include <cmath>

namespace {
using namespace xui;
using collections_test::require;
class Probe : public Element {
public:
    std::size_t measurements{};
    bool fail{};
    std::function<void()> measuring, arranging;
    Size measure(Size available) override {
        ++measurements;
        if (fail) throw std::runtime_error("Injected measurement failure");
        if (measuring) measuring();
        return Element::measure(available);
    }
    void arrange(Rect bounds) override {
        if (arranging) arranging();
        Element::arrange(bounds);
    }
};
void close(float actual, float expected, const char* message) {
    require(std::isfinite(actual) && std::abs(actual - expected) < 0.001f, message);
}
template<class F> void timed(const char* name, std::size_t operations, F work) {
    const auto private_before = memory();
    calls = bytes = 0;
    const auto before_cpu = cpu();
    counting = true;
    const auto start = std::chrono::steady_clock::now();
    const auto checksum = work();
    const auto elapsed = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
    counting = false;
    const auto after_cpu = cpu();
    require(calls == 0 && bytes == 0, "Long public-operation loop allocates nothing");
    require(after_cpu.kernel >= before_cpu.kernel && after_cpu.user >= before_cpu.user, "Monotonic loop CPU");
    std::cout << name << " operations=" << operations << " checksum=" << checksum
        << " allocations=" << calls << " allocated_bytes=" << bytes << " elapsed_ms=" << elapsed
        << " kernel_before_100ns=" << before_cpu.kernel << " kernel_after_100ns=" << after_cpu.kernel
        << " user_before_100ns=" << before_cpu.user << " user_after_100ns=" << after_cpu.user
        << " thread_cpu_ms=" << (after_cpu.kernel - before_cpu.kernel + after_cpu.user - before_cpu.user) / 10000.0
        << " private_before=" << private_before << " private_after=" << memory() << '\n';
}
void layout(bool styled) {
    Stack root(Axis::vertical);
    root.set_spacing(2);
    root.set_padding({3, 4, 5, 6});
    PartStyleValues style;
    style.horizontal_alignment = StyleAlignment::center;
    style.vertical_alignment = StyleAlignment::end;
    if (styled) root.set_control_style_values(StylePart::root, style);
    std::vector<std::shared_ptr<Probe>> leaves;
    for (int row = 0; row < 8; ++row) {
        auto group = std::make_shared<Stack>(Axis::horizontal);
        group->set_spacing(1);
        if (styled) group->set_control_style_values(StylePart::root, style);
        for (int column = 0; column < 8; ++column) {
            auto child = std::make_shared<Probe>();
            child->set_preferred_size({12, 16});
            group->add(child, column % 2 ? 1 : 0);
            leaves.push_back(std::move(child));
        }
        root.add(std::move(group), row % 2 ? 1 : 0);
    }
    const auto frame = [&](int index) {
        const auto width = 640.0f + index % 31;
        const auto height = 480.0f + index % 17;
        const auto measured = root.measure({width, height});
        close(measured.width, width, "Nested flex retains measured width");
        close(measured.height, height, "Nested flex retains measured height");
        root.arrange({7, 9, width, height});
    };
    for (int i = 0; i < 1000; ++i) frame(i);
    const auto before = leaves.front()->measurements;
    constexpr int frames = 300000;
    timed(styled ? "layout_warm_styled" : "layout_warm_plain", frames, [&] {
        for (int i = 0; i < frames; ++i) frame(i);
        return leaves.front()->measurements - before;
    });
    require(leaves.front()->measurements == before + frames * 3, "Long layout keeps exact child measurement count");
}
void interaction() {
    constexpr std::size_t count = 1000000, operations = 2000000;
    auto items = std::make_shared<std::vector<FileItem>>();
    items->reserve(count);
    for (std::size_t i = 0; i < count; ++i) {
        auto number = std::to_wstring(i);
        std::wstring name = L"File-" + std::wstring(7 - number.size(), L'0') + number + L".txt";
        items->push_back({static_cast<ItemId>((count - i) * 17 + 1), name, L"C:\\synthetic\\" + name, false});
    }
    auto source = FileSnapshot::build(items);
    auto all = FilteredView::build(source, {});
    FileList list;
    list.set_view(all);
    list.set_viewport_height(320);
    std::size_t events{};
    list.on_selection_change([&] { ++events; });
    const auto* const indices = all->indices().data();
    const auto perform = [&](std::size_t i) {
        const std::size_t index = (i * 7919) % count;
        list.select(index, false);
        list.focus_item((index + 1) % count);
        const auto selected = list.model().selected_index();
        const auto focused = list.focused_index();
        require(selected == index && focused == (index + 1) % count, "Long interaction resolves exact identities");
        require(list.model().selected_item()->id == (*items)[index].id, "Long interaction resolves exact selected item");
        const auto rows = list.visible_rows();
        require(rows.end - rows.begin <= 14, "Long interaction keeps bounded viewport work");
        return *selected + *focused;
    };
    for (std::size_t i = 0; i < 20000; ++i) perform(i);
    events = 0;
    timed("interaction_warm_million", operations, [&] {
        std::uint64_t checksum{};
        for (std::size_t i = 0; i < operations; ++i) checksum += perform(i);
        require(checksum == operations * (count - 1), "Long interaction performs exact indexed work");
        return checksum;
    });
    require(events == operations && list.model().view() == all && all->indices().data() == indices,
        "Long interaction preserves callbacks and the shared immutable view");
}
}
int main() {
    try { layout(false); layout(true); interaction(); return 0; }
    catch (const std::exception& error) { std::cerr << error.what() << '\n'; return 1; }
}
